  const prompt = `
    You are an expert content creator for Xiaohongshu (Little Red Book). 
    Help me polish this academic paper summary into a viral, high-value post.
    Keep the tone professional yet engaging, use emojis appropriately, and make it concise.

    Input Data:
    - Catchy Title Recommendation: ${data.catchyTitle}
    - Paper Title: ${data.paperTitle}
    - Research Question: ${data.researchQuestion}
    - Key Contribution: ${data.keyContribution}
    - Value Highlight: ${data.oneSentenceValue}

    Tasks:
    1. Create a "Catchy Title" (Max 15 chars) that would attract attention on Xiaohongshu.
    2. Refine the "One Sentence Value" to be extremely punchy.
    3. Generate 3-5 trending hashtags based on the content.

    Return the result in JSON format.
  `;

  try {
    // Correctly calling generateContent with model name and parameters directly.
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            catchyTitle: { type: Type.STRING },
            oneSentenceValue: { type: Type.STRING },
            tags: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["catchyTitle", "oneSentenceValue", "tags"]
        }
      }
    });

    // Use .text property to access generated content.
    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (error) {
    console.error("Gemini Polishing Error:", error);
    return {};
  }
};

import React, { useState, useRef, useEffect } from 'react';
import html2canvas from 'html2canvas';
import { 
  Plus, 
  Trash2, 
  Download, 
  Sparkles, 
  Share2, 
  Info, 
  Settings, 
  Palette,
  FileText,
  Target // Added Target import which was missing
} from 'lucide-react';
import { PaperNoteData, ThemeType } from './types';
import { polishNoteContent } from './services/geminiService';
import PreviewCard from './components/PreviewCard';

const INITIAL_DATA: PaperNoteData = {
  catchyTitle: '',
  paperTitle: '',
  authors: '',
  source: '',
  oneSentenceValue: '',
  researchQuestion: '',
  keyContribution: '',
  methods: [],
  strengths: [],
  limitations: [],
  takeaways: [],
  connection: '',
  questions: '',
  tags: ['论文笔记', '科研干货'],
  username: ''
};

export default function App() {
  const [data, setData] = useState<PaperNoteData>(INITIAL_DATA);
  const [theme, setTheme] = useState<ThemeType>('cream');
  const [isPolishing, setIsPolishing] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  const handleInputChange = (field: keyof PaperNoteData, value: string | string[]) => {
    setData(prev => ({ ...prev, [field]: value }));
  };

  const handleListChange = (field: keyof PaperNoteData, index: number, value: string) => {
    const list = [...(data[field] as string[])];
    list[index] = value;
    setData(prev => ({ ...prev, [field]: list }));
  };

  const addListItem = (field: keyof PaperNoteData) => {
    const list = [...(data[field] as string[])];
    list.push('');
    setData(prev => ({ ...prev, [field]: list }));
  };

  const removeListItem = (field: keyof PaperNoteData, index: number) => {
    const list = [...(data[field] as string[])];
    list.splice(index, 1);
    setData(prev => ({ ...prev, [field]: list }));
  };

  const handlePolish = async () => {
    if (!data.paperTitle) {
      alert("请至少输入论文标题后再进行AI优化");
      return;
    }
    setIsPolishing(true);
    try {
      const polished = await polishNoteContent(data);
      setData(prev => ({ ...prev, ...polished }));
    } catch (error) {
      console.error(error);
    } finally {
      setIsPolishing(false);
    }
  };

  const handleExport = async () => {
    if (!cardRef.current) return;
    try {
      // Increase quality by using a larger canvas
      const canvas = await html2canvas(cardRef.current, {
        scale: 3, // 3x scale for crisp 1080x1440 output
        useCORS: true,
        backgroundColor: null,
      });
      const link = document.createElement('a');
      link.download = `PaperNote_${data.paperTitle.slice(0, 10)}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (err) {
      console.error('Export error:', err);
    }
  };

