            {isPolishing ? 'AI正在琢磨爆款词汇...' : 'AI一键优化文案'}
          </button>

          {/* Core Content Section */}
          <section>
            <div className="flex items-center gap-2 mb-4 text-gray-800">
              <Target size={18} className="text-[#ff2442]" />
