              theme={activeTheme} 
            />
          </div>

          {/* Methods & Takeaways Group */}
          <div className="grid grid-cols-2 gap-3">
             <div className="space-y-2">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`p-1 rounded-md ${activeTheme.iconColor}`}>
                    <Workflow size={14} />
                  </span>
                  <h3 className={`font-bold text-sm ${activeTheme.textPrimary}`}>核心方法</h3>
                </div>
                <ul className="pl-8 space-y-0.5">
                  {data.methods.slice(0, 3).map((item, i) => (
                    <li key={i} className={`text-[10px] ${activeTheme.textPrimary} truncate`}>{i+1}. {item}</li>
                  ))}
                  {data.methods.length === 0 && <li className="text-[10px] text-gray-300 italic pl-0 truncate">待填写...</li>}
                </ul>
             </div>

             <div className="space-y-2">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`p-1 rounded-md ${activeTheme.iconColor}`}>
                    <Bookmark size={14} />
                  </span>
                  <h3 className={`font-bold text-sm ${activeTheme.textPrimary}`}>核心要点</h3>
                </div>
                <ul className="pl-8 space-y-0.5">
                  {data.takeaways.slice(0, 3).map((item, i) => (
                    <li key={i} className={`text-[10px] ${activeTheme.textPrimary} truncate`}>• {item}</li>
                  ))}
                  {data.takeaways.length === 0 && <li className="text-[10px] text-gray-300 italic pl-0 truncate">待填写...</li>}
                </ul>
             </div>
          </div>

          {/* Strengths & Limitations */}
          <div className="grid grid-cols-2 gap-3">
            <MiniSection 
              icon={<CheckCircle2 size={12} className="text-green-500" />} 
              title="优势点" 
              items={data.strengths} 
              theme={activeTheme}
            />
            <MiniSection 
              icon={<AlertCircle size={12} className="text-amber-500" />} 
              title="局限性" 
              items={data.limitations} 
              theme={activeTheme}
            />
          </div>

          {/* Questions after reading */}
          <Section 
            icon={<HelpCircle size={14} />} 
            title="存疑/待探讨" 
            content={data.questions} 
            theme={activeTheme} 
          />

          {/* Connection to my research - Moved below Questions as requested */}
          <Section 
            icon={<GitBranch size={14} />} 
            title="与我研究的相关性" 
            content={data.connection} 
            theme={activeTheme} 
          />
        </div>

        {/* Footer */}
        <footer className="mt-4 pt-4 border-t border-dashed border-gray-200">
          <div className="flex flex-wrap gap-2 mb-3">
            {data.tags.map((tag, i) => (
              <span key={i} className="text-[#3b82f6] text-[10px] font-medium">#{tag}</span>
            ))}
          </div>
          <div className="flex justify-between items-center text-[10px] text-gray-400">
            <div className="flex items-center gap-1">
              <div className="w-5 h-5 rounded-full bg-[#ff2442] flex items-center justify-center text-white font-bold text-[8px]">
                {data.username ? data.username[0].toUpperCase() : 'P'}
              </div>
              <span className="font-bold">@{data.username || '科研笔记达人'}</span>
            </div>
            <div className="flex items-center gap-1 opacity-50">
              <Link size={10} /> 扫码查看全文
            </div>
          </div>
        </footer>
      </div>
    </div>
  );
};

const Section: React.FC<{ icon: React.ReactNode, title: string, content: string, theme: any }> = ({ icon, title, content, theme }) => (
  <div className="space-y-1">
    <div className="flex items-center gap-2 mb-1">
      <span className={`p-1 rounded-md ${theme.iconColor}`}>{icon}</span>
      <h3 className={`font-bold text-sm ${theme.textPrimary}`}>{title}</h3>
    </div>
    <p className={`text-[11px] ${theme.textPrimary} pl-8 leading-relaxed line-clamp-2`}>
      {content || '请输入相关内容...'}
    </p>
  </div>
);

const MiniSection: React.FC<{ icon: React.ReactNode, title: string, items: string[], theme: any }> = ({ icon, title, items, theme }) => (
  <div className={`${theme.cardBg} p-2 rounded-lg`}>
    <div className="flex items-center gap-1 mb-1">
      {icon}
      <h4 className={`text-[10px] font-bold ${theme.textPrimary}`}>{title}</h4>
    </div>
    <ul className="space-y-0.5">
      {items.slice(0, 2).map((item, i) => (
        <li key={i} className={`text-[9px] ${theme.textPrimary} leading-tight truncate`}>• {item}</li>
      ))}
      {items.length === 0 && <li className="text-[9px] text-gray-300 italic">暂无内容</li>}
    </ul>
  </div>
);

export default PreviewCard;
